yaml:
kind: Policy
metadata:
  name: order-events
  consumer: order-events
spec:
  retry:    { max: 5, base: 30s, factor: 2, cap: 30m, jitter: 0.2 }
  breaker:  { window: 60s, threshold: 20 }
  probe:    { type: canary, every: 30s, cap: 5m }
  drain:    { rate: 50 }
  recovery: { mode: ack, topic: opendlq.ack, timeout: 10s }
  ttl: 72h
